import{d as s,C as t,o as h,c as u,E as a,a3 as n}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"复卦","description":"第二十四卦·地雷复——雷在地中，一阳来复。","frontmatter":{"title":"复卦","description":"第二十四卦·地雷复——雷在地中，一阳来复。","category":"hexagram","aliases":["复","地雷复"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-24.md","filePath":"yijing/hexagrams/hexagram-24.md","lastUpdated":1787730063000}'),g={name:"yijing/hexagrams/hexagram-24.md"},y=s({...g,setup(p){const l=[{id:"buyuanfu",term:"不远复",pinyin:"bù yuǎn fù",meaning:"偏离不远就回来。最好的复，是在偏离刚发生的时候就回来。"},{id:"wuzhihui",term:"无祗悔",pinyin:"wú zhī huǐ",meaning:"不至于悔恨。祗，仅仅、至于。刚偏就回，自然无悔。"},{id:"xiufu",term:"休复",pinyin:"xiū fù",meaning:"美好的回归。靠近善、借力回，不孤军奋战。"},{id:"pinfu",term:"频复",pinyin:"pín fù",meaning:"屡次反复、挣扎着回来。蹙眉、承认沉没成本也愿意回。"},{id:"zhongxingdufu",term:"中行独复",pinyin:"zhōng xíng dú fù",meaning:"行于中道、独自回归。看见方向，特立独行地走过去。"},{id:"dunfu",term:"敦复",pinyin:"dūn fù",meaning:"敦厚而回归。多次积累后的厚度，收成了本能。"},{id:"mifu",term:"迷复",pinyin:"mí fù",meaning:"迷失于回归。为了复而复，方向从未对过。"},{id:"zaisheng",term:"灾眚",pinyin:"zāi shěng",meaning:"灾祸。眚，过失、灾异。"},{id:"yixiushen",term:"以修身",pinyin:"yǐ xiū shēn",meaning:"用来修养身心。不远之复，以修身也——最初就觉察，是最好的修身。"},{id:"yixiaren",term:"以下仁",pinyin:"yǐ xià rén",meaning:"因为亲附仁者。休复之吉，以下仁也——选择和谁在一起，本身就是一种复。"},{id:"yiwujiu",term:"义无咎",pinyin:"yì wú jiù",meaning:"义理上无咎。频复之厉，义无咎也——不是没有损失，是没有骗自己。"},{id:"yicongdao",term:"以从道",pinyin:"yǐ cóng dào",meaning:"因为跟从正道。中行独复，以从道也。"},{id:"zhongyizikao",term:"中以自考",pinyin:"zhōng yǐ zì kǎo",meaning:"居中而自我省察。敦复无悔，中以自考也。"},{id:"fanjundao",term:"反君道",pinyin:"fǎn jūn dào",meaning:"违反君道。迷复之凶，反君道也——忘记了为什么要回。"}],e=[{position:"初九",type:"yang",text:"不远复，无祗悔，元吉。",xiang:"不远之复，以修身也。",textModern:"刚刚偏离，还没走远，回头是自然的，代价几乎为零。元吉不是奖励，是描述——在最早的时刻认出偏离、转身，本来就是这样的结果。",xiangModern:"偏离不远就回归，用来修养身心——在最初就觉察，是最好的修身。"},{position:"六二",type:"yin",text:"休复，吉。",xiang:"休复之吉，以下仁也。",textModern:"靠近善、借力回——六二本身是阴爻，但紧靠初九这个阳爻，被正确的环境带回来。复不一定要孤军奋战。",xiangModern:"休复的吉，在于亲附仁者——选择和谁在一起，本身就是一种复。"},{position:"六三",type:"yin",text:"频复，厉，无咎。",xiang:"频复之厉，义无咎也。",textModern:"走得比六二远，回头意味着承认之前的投入不算数——沉没成本的重量。但清清楚楚知道代价，还是转身了；全程清醒、全程诚实，所以无咎。",xiangModern:"频复的厉，在义理上无咎——不是没有损失，是因为没有骗自己。"},{position:"六四",type:"yin",text:"中行独复。",xiang:"中行独复，以从道也。",textModern:"被五个阴爻包围，待着很安全，但它看见了下面的初九，选择独自往那里走。这个独不是孤独，是特立独行的独——看见方向，平静地走过去。",xiangModern:"行于中道而独自回归，因为跟从正道——不随波逐流不是目的，看见初九并走过去才是。"},{position:"六五",type:"yin",text:"敦复，无悔。",xiang:"敦复无悔，中以自考也。",textModern:"多次积累后的厚度——经历了足够多次的频复、独复、挣扎着复，内心生出一种东西：不需要再证明、再解释，厚在那里，就是那里。收，变成了本能。",xiangModern:"敦复而无悔，在于居中而自我省察——该放下就放下，放完了心里干净。"},{position:"上六",type:"yin",text:"迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。",xiang:"迷复之凶，反君道也。",textModern:"为了复而复，方向从未对过——形式还在，灵魂没了。不是不努力，是在迷宫里跑圈，跑得越快，离出口越远；灾眚不是天降惩罚，是长期在错误方向上消耗自己。",xiangModern:"迷复的凶，在于违反君道——忘记了为什么要回，只记得要回这个动作本身。"}];return(m,i)=>{const o=t("DaoHexagramViewer"),r=t("DaoHexagramYaoCards"),d=t("DaoKeywordCards");return h(),u("div",null,[a(o,{name:"复",fullName:"地雷复",upper:"☷",lower:"☳",guaCi:"复，亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。",pinyin:["fù"],element:"土",direction:"西南",insight:"一阳来复，阳气萌生；复不是动作，是清醒，清醒的质量决定复的质量。",guaSlug:"24dileifu",lines:e}),i[0]||(i[0]=n("",9)),a(r,{element:"土",guaSlug:"24dileifu",glossary:l,items:e}),i[1]||(i[1]=n("",22)),a(d,{title:"字词释义",items:[{term:"复",pinyin:["fù"],meaning:"回来。不是终点，是重新找到方向的起点。"},{term:"不远复",pinyin:["bù","yuǎn","fù"],meaning:"偏离不远就回来。"},{term:"休复",pinyin:["xiū","fù"],meaning:"美好的回归，靠近善、借力回。"},{term:"频复",pinyin:["pín","fù"],meaning:"屡次反复、挣扎着回来。"},{term:"中行独复",pinyin:["zhōng","xíng","dú","fù"],meaning:"行于中道、独自回归。"},{term:"敦复",pinyin:["dūn","fù"],meaning:"敦厚而回归，收成了本能。"},{term:"迷复",pinyin:["mí","fù"],meaning:"迷失于回归，为了复而复。"},{term:"祗",pinyin:["zhī"],meaning:"仅仅、至于。「无祗悔」即不至于悔恨。"},{term:"灾眚",pinyin:["zāi","shěng"],meaning:"灾祸。眚，过失、灾异。"},{term:"七日来复",pinyin:["qī","rì","lái","fù"],meaning:"阳气七日一循环，天道如此，人道亦然。"}]}),i[2]||(i[2]=n("",22))])}}});export{x as __pageData,y as default};
